// Test outbound network via fetch to a couple of render endpoints.
const results = {};
try {
  const r = await fetch('https://kroki.io/plantuml/svg', {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain' },
    body: '@startuml\nBob -> Alice : hello\n@enduml',
  });
  results.kroki = { status: r.status, ct: r.headers.get('content-type') };
} catch (e) { results.kroki = 'ERR ' + e.message; }
try {
  const r = await fetch('https://www.plantuml.com/plantuml/svg/SoWkIImgAStDuNBAJrBGjLDmpCbC10pL', { method: 'GET' });
  results.plantuml = { status: r.status, ct: r.headers.get('content-type') };
} catch (e) { results.plantuml = 'ERR ' + e.message; }
return results;

